/// <summary>
/// Computed column for nameAlias
/// Could add InventTable with a relation to InventTransferLine datasource because of error
/// Data entity field InventTransferOrderLineV2Entity.ItemNumber is currently mapped to InventTransferLine.ItemId 
/// but it should be mapped to METInventTable.ItemId because InventTransferLine.ItemId is a foreign key field referencing METInventTable.ItemId.
/// </summary>
/// <returns></returns>
public static str metLineDescription()
{
    SysDictTable inventTable = new SysDictTable(tableNum(InventTable));
    str itemId = SysComputedColumn::returnField(tablestr(InventTransferOrderLineV2Entity), dataEntityDataSourceStr(InventTransferOrderLineV2Entity, InventTransferLine), fieldStr(InventTransferLine, ItemId));
    str dataAreaId = SysComputedColumn::returnField(tablestr(InventTransferOrderLineV2Entity), dataEntityDataSourceStr(InventTransferOrderLineV2Entity, InventTransferLine), fieldStr(InventTransferLine, DataAreaId));

    str query = strFmt("SELECT NAMEALIAS FROM %1 WHERE %1.ITEMID = %2 AND %1.DATAAREAID = %3",
        inventTable.name(),
        itemId,
        dataAreaId);

    return query;
}

/// <summary>
/// Computed column for itemName
/// Could add InventTable with a relation to InventTransferLine datasource because of error
/// Data entity field InventTransferOrderLineV2Entity.ItemNumber is currently mapped to InventTransferLine.ItemId
/// but it should be mapped to METInventTable.ItemId because InventTransferLine.ItemId is a foreign key field referencing METInventTable.ItemId.
/// </summary>
/// <returns></returns>
public static str metItemName()
{
    SysDictTable inventTable = new SysDictTable(tableNum(InventTable));
    SysDictTable ecoResProductTranslation = new SysDictTable(tableNum(EcoResProductTranslation));
    str itemId = SysComputedColumn::returnField(tablestr(InventTransferOrderLineV2Entity), dataEntityDataSourceStr(InventTransferOrderLineV2Entity, InventTransferLine), fieldStr(InventTransferLine, ItemId));
    str dataAreaId = SysComputedColumn::returnField(tablestr(InventTransferOrderLineV2Entity), dataEntityDataSourceStr(InventTransferOrderLineV2Entity, InventTransferLine), fieldStr(InventTransferLine, DataAreaId));

    const str enau = 'en-au';

    str query = strFmt("select NAME from %1 join %2 on %2.PRODUCT = %1.PRODUCT WHERE INVENTTABLE.ITEMID = %3 AND INVENTTABLE.DATAAREAID = %4 AND %1.LANGUAGEID = '%5'",
        ecoResProductTranslation.name(),
        inventTable.name(),
        itemId,
        dataAreaId,
        enau);

    return query;
}
